import { actionObj, object_group } from './actObject';
import { getUuid } from '../utils';
//方法资源分组
export var funcGroup;
(function (funcGroup) {
    funcGroup["universalTool"] = "\u901A\u7528\u5DE5\u5177";
    funcGroup["storages"] = "\u7F13\u5B58";
    funcGroup["pageOption"] = "\u9875\u9762\u8D44\u6E90";
})(funcGroup || (funcGroup = {}));
//方法编码-需要保证唯一性
export var funcCode;
(function (funcCode) {
    funcCode["propertiesInPage"] = "propertiesInPage";
    funcCode["methodsInPage"] = "methodsInPage";
    funcCode["dictionary"] = "dictionary";
    funcCode["thirtyApi"] = "thirtyApi";
    funcCode["oneParamJude"] = "oneParamJude";
    funcCode["notificationDialog"] = "notificationDialog";
    funcCode["fixedVal"] = "fixedVal";
    funcCode["leadToOtherPage"] = "leadToOtherPage";
    funcCode["windowLocalStorage"] = "windowLocalStorage";
    funcCode["jsFunction"] = "jsFunction";
})(funcCode || (funcCode = {}));
//反射，所有方法的实体类
var allActFunctions = [];
export function resourceFuncAttr(name, desc, funcGroup, funcCode, funcStack, inparams, outParam, isJudeNode) {
    return function (target) {
        !target.prototype.$lyl_actFunc && (target.prototype.$lyl_actFunc = {});
        target.prototype.$lyl_actFunc.funcCode = funcCode;
        target.prototype.$lyl_actFunc.funcStack = funcStack;
        target.prototype.$lyl_actFunc.funcGroup = funcGroup;
        target.prototype.$lyl_actFunc.inparams = inparams;
        target.prototype.$lyl_actFunc.outParam = outParam;
        target.prototype.$lyl_actFunc.name = name;
        target.prototype.$lyl_actFunc.isJudeNode = isJudeNode;
        target.prototype.$lyl_actFunc.desc = desc;
        allActFunctions.push(target);
    };
}
export { allActFunctions };
//actFunc转actObj
export function funcToObj(actFunc) {
    var obj = new actionObj();
    obj.id = getUuid();
    obj.name = actFunc.prototype.$lyl_actFunc.name;
    obj.funcCode = actFunc.prototype.$lyl_actFunc.funcCode;
    obj.description = actFunc.prototype.$lyl_actFunc.desc;
    obj.inputParams = actFunc.prototype.$lyl_actFunc.inparams;
    obj.outParam = actFunc.prototype.$lyl_actFunc.outParam;
    obj.isJudeNode = actFunc.prototype.$lyl_actFunc.isJudeNode;
    obj.resourceFilter = {};
    return obj;
}
//根据方法的信息，把方法的元数据组织成树结构，提供给设计器使用
export function getFuncObjsTree() {
    var res = []; //object_group
    var _loop_1 = function (index) {
        var actFunc = allActFunctions[index];
        var group = actFunc.prototype.$lyl_actFunc.funcGroup;
        var findGroup = res.find(function (o) { return o.title === group; });
        if (!findGroup) {
            findGroup = new object_group();
            findGroup.key = getUuid();
            findGroup.title = group;
            findGroup.childrenGroups = [];
            findGroup.childrenObjs = [];
            res.push(findGroup);
        }
        var actObj = funcToObj(actFunc);
        findGroup.childrenObjs.push(actObj);
    };
    for (var index = 0; index < allActFunctions.length; index++) {
        _loop_1(index);
    }
    return res;
}
//获取指定类型的方法元数据
export function getFuncObjByGroup(group) {
    var funcs = allActFunctions.filter(function (o) { return o.prototype.$lyl_actFunc.funcGroup == group; });
    var objs = [];
    for (var index = 0; index < funcs.length; index++) {
        var element = funcs[index];
        objs.push(funcToObj(element));
    }
    return objs;
}
export function getFuncByType(funcCode) {
    // window.console.log('行为代码2', funcCode)
    var res = allActFunctions.find(function (o) { return o.prototype.$lyl_actFunc.funcCode == funcCode; });
    try {
        return new res();
    }
    catch (error) {
        return null;
    }
}
export function getFuncObjByType(funcCode) {
    // window.console.log('行为代码2', funcCode)
    var res = allActFunctions.find(function (o) { return o.prototype.$lyl_actFunc.funcCode == funcCode; });
    try {
        return funcToObj(res);
    }
    catch (error) {
        return null;
    }
}
