if (!window.$designany_allPages) {
    ;
    window.$designany_allPages = [];
}
export function DPageAttr(paltform, preOrDesign) {
    return function (target) {
        !target.prototype.$lyl_page && (target.prototype.$lyl_page = {});
        target.prototype.$lyl_page.paltform = paltform;
        target.prototype.$lyl_page.preOrDesign = preOrDesign;
        var layoutInfo = { paltform: paltform, preOrDesign: preOrDesign, component: target };
        window.$designany_allPages.push(layoutInfo);
    };
}
export function findPageByPaltform(paltform, preOrDesign) {
    return window.$designany_allPages.find(function (o) { return o.paltform === paltform && o.preOrDesign === preOrDesign; }).component;
}
